import React from "react";
import { Routes, Route } from "react-router-dom";
import Login from "./Login";
import Signup from "./Signup";
import TeacherDashboard from "./TeacherDashboard";
import StudentDashboard from "./StudentDashboard";
import Courses from "./Courses";
import Planner from "./Planner";
import MainLayout from "./MainLayout";
import ProtectedRoute from "./ProtectedRoute";
import AssignmentsTeacher from "./AssignmentsTeacher";
import AssignmentsStudent from "./AssignmentsStudent";

function App() {
  return (
    <Routes>
      <Route path="/teacher-assignments" element={<AssignmentsTeacher />} />
      <Route path="/student-assignments" element={<AssignmentsStudent />} />
      <Route path="/" element={<Login />} />
      <Route path="/signup" element={<Signup />} />

      <Route
        element={
          <ProtectedRoute>
            <MainLayout />
          </ProtectedRoute>
        }
      >
        <Route
          path="/teacher-dashboard"
          element={
            <ProtectedRoute allowedRole="teacher">
              <TeacherDashboard />
            </ProtectedRoute>
          }
        />

        <Route
          path="/student-dashboard"
          element={
            <ProtectedRoute allowedRole="student">
              <StudentDashboard />
            </ProtectedRoute>
          }
        />

        <Route
          path="/courses"
          element={
            <ProtectedRoute>
              <Courses />
            </ProtectedRoute>
          }
        />

        <Route
          path="/planner"
          element={
            <ProtectedRoute allowedRole="student">
              <Planner />
            </ProtectedRoute>
          }
        />
      </Route>
    </Routes>
  );
}

export default App;
